# Remote storage browser: list buckets and keys from a storage namespace tree.
store = {'photos': {'2024': {'a.jpg': 1200}}, 'docs': {'r.pdf': 500}}
def list_prefix(tree, prefix=""):
    out = []
    for key, val in sorted(tree.items()):
        full = prefix + key
        if isinstance(val, dict):
            out.append(full + "/")
            out += list_prefix(val, full + "/")
        else:
            out.append(full + f"  ({val} bytes)")
    return out
target = ""
node = store
for part in target.strip("/").split("/"):
    if part: node = node.get(part, {})
print(f"Listing {target or '/'}:")
for line in list_prefix(node, target.rstrip("/") + "/" if target else "")[:10]:
    print(" ", line)

